"""Token parsing helpers."""

from dataclasses import dataclass

from src.auth.exceptions import RefreshTokenExpired, TokenSubjectMissing


@dataclass(frozen=True)
class RefreshPayload:
    subject: str
    expires_at: int
    token_id: str


def decode_refresh_payload(raw_token: str) -> RefreshPayload:
    """Decode a refresh credential into a payload."""
    if raw_token == "expired":
        raise RefreshTokenExpired("refresh credential expired")
    if raw_token == "missing-subject":
        raise TokenSubjectMissing("subject is required")
    return RefreshPayload(subject="user-123", expires_at=4_102_444_800, token_id=raw_token)


def build_access_token(subject: str) -> str:
    """Build an access token for a subject."""
    return f"access:{subject}"

"""Order business logic."""

from src.common.events import EventBus
from src.inventory.service import InventoryService
from src.orders.events import order_cancelled_event


class OrderService:
    """Coordinates order state transitions."""

    def __init__(
        self,
        event_bus: EventBus | None = None,
        inventory: InventoryService | None = None,
    ) -> None:
        self.event_bus = event_bus or EventBus()
        self.inventory = inventory or InventoryService()

    def cancel_order(self, order_id: str, reason: str) -> dict:
        released = self.inventory.release_for_order(order_id)
        self.event_bus.publish(order_cancelled_event(order_id, reason))
        return {"order_id": order_id, "released_reservations": released}

    def create_order(self, order_id: str, sku: str, quantity: int) -> dict:
        reservation = self.inventory.reserve_for_order(order_id, sku, quantity)
        return {"order_id": order_id, "reservation": reservation}

"""Domain event primitives."""

from dataclasses import dataclass
from typing import Callable


ORDER_CANCELLED = "order.cancelled"
PAYMENT_WEBHOOK_ACCEPTED = "billing.webhook.accepted"
INVOICE_RETRY_REQUESTED = "billing.invoice.retry_requested"


@dataclass(frozen=True)
class EventEnvelope:
    """Event wrapper shared by producers and consumers."""

    name: str
    payload: dict


class EventBus:
    """In-memory event bus for the fixture."""

    def __init__(self) -> None:
        self._handlers: dict[str, list[Callable[[EventEnvelope], None]]] = {}

    def subscribe(self, name: str, handler: Callable[[EventEnvelope], None]) -> None:
        self._handlers.setdefault(name, []).append(handler)

    def publish(self, event: EventEnvelope) -> None:
        for handler in self._handlers.get(event.name, []):
            handler(event)

